package com.cowave.search.inbound_adapter.handler.listener

import com.cowave.search.inbound_adapter.handler.ConsumerCallbackManager
import com.cowave.shared.utils.logger
import org.apache.kafka.clients.consumer.Consumer
import org.apache.kafka.clients.consumer.ConsumerRecord
import org.apache.kafka.clients.consumer.OffsetAndMetadata
import org.apache.kafka.common.TopicPartition
import org.springframework.kafka.listener.ConsumerSeekAware
import kotlin.collections.component1
import kotlin.collections.component2
import kotlin.collections.forEach
import kotlin.getValue

abstract class FlinkCdcBatchListener(
    val groupId: String,
    val consumerCallbackManager: ConsumerCallbackManager,
) : ConsumerSeekAware {
    private val logger by logger()

    interface ConsumerManager<K, V> {
        fun records(): List<ConsumerRecord<K, V>>

        fun commit()
    }

    fun <K, V> createConsumerManager(
        data: List<ConsumerRecord<K, V>>,
        consumer: Consumer<*, *>,
        skipPredicate: (V) -> Boolean = { false },
    ): ConsumerManager<K, V> =
        object : ConsumerManager<K, V> {
            private val logger by logger()
            private val offsetMap: MutableMap<TopicPartition, Long> = mutableMapOf()
            private val seekMap: MutableMap<TopicPartition, Long> = mutableMapOf()
            private val refinedData: MutableList<ConsumerRecord<K, V>> = mutableListOf()

            init {
                logger.info { "CommitManager created. data size: ${data.size}" }

                data
                    .groupBy { TopicPartition(it.topic(), it.partition()) }
                    .forEach { (tp, records) ->
                        val refined: MutableList<ConsumerRecord<K, V>> = mutableListOf()

                        if (skipPredicate(records.last().value())) {
                            seekMap[tp] = records.last().offset()
                            refined.addAll(records.dropLast(1))
                        } else {
                            refined.addAll(records)
                        }

                        offsetMap[tp] = refined.last().offset()
                        refinedData.addAll(refined)
                    }
            }

            override fun records(): List<ConsumerRecord<K, V>> = refinedData.toList()

            override fun commit() {
                if (offsetMap.isEmpty()) {
                    logger.warn { "No offset to commit" }
                }

                offsetMap.forEach { (tp, offset) ->
                    consumer.commitSync(mapOf(tp to OffsetAndMetadata(offset)))
                }

                seekMap.forEach { (tp, offset) ->
                    val cbm = consumerCallbackManager.getConsumerCallback(groupId, tp.topic(), tp.partition())
                    cbm.callback.seek(tp.topic(), tp.partition(), offset)
                }
            }
        }

    override fun registerSeekCallback(callback: ConsumerSeekAware.ConsumerSeekCallback) {
        // Do nothing
    }

    override fun onPartitionsAssigned(
        assignments: MutableMap<TopicPartition, Long>,
        callback: ConsumerSeekAware.ConsumerSeekCallback,
    ) {
        assignments.keys.forEach {
            consumerCallbackManager.register(groupId, it.topic(), it.partition(), callback)
        }
    }

    override fun onPartitionsRevoked(partitions: MutableCollection<TopicPartition>) {
        partitions.forEach {
            consumerCallbackManager.revoke(groupId, it.topic(), it.partition())
        }
    }

    override fun onIdleContainer(
        assignments: MutableMap<TopicPartition, Long>,
        callback: ConsumerSeekAware.ConsumerSeekCallback,
    ) {
        assignments.keys.forEach {
            checkToSeek(it.topic(), it.partition())
        }
    }

    protected fun rewindIfNeeded() {
        consumerCallbackManager
            .getAllConsumerCallbacks()
            .forEach { c ->
                if (c.shouldSeek) {
                    logger.info {
                        "[Consumer] Try to seek offset. " +
                            "groupId=[${c.groupId}], topic=[${c.topic}], partition=[${c.partition}], offset=[${c.offset}]"
                    }
                    c.callback.seek(c.topic, c.partition, c.offset)
                    c.reset()
                }
            }
    }

    protected fun checkToSeek(
        topic: String,
        partition: Int,
    ) {
        val c = consumerCallbackManager.getConsumerCallback(groupId, topic, partition)
        if (c.shouldSeek) {
            logger.info {
                "[Consumer] Try to seek offset. " +
                    "groupId=[$groupId], topic=[$topic], partition=[$partition], offset=[${c.offset}]"
            }
            c.callback.seek(topic, partition, c.offset)
            c.reset()
        }
    }
}

