package com.cowave.search.inbound_adapter.handler

import com.cowave.search.inbound_adapter.handler.dto.ConsumerCallback
import com.cowave.search.inbound_adapter.handler.dto.ConsumerGroupOffsetSnapshot
import com.cowave.shared.utils.logger
import org.springframework.kafka.listener.ConsumerSeekAware
import org.springframework.stereotype.Component
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantLock

/**
 * Consumer offset을 중앙 관리하는 컴포넌트
 * 멀티스레드 안전성을 위해 요청을 큐에 저장하고 idle 상태에서 처리
 */
@Component
class ConsumerCallbackManager {
    private val logger by logger()
    private val consumerCallbacks = ConcurrentHashMap<String, ConsumerCallback>()
    private val lock = ReentrantLock()

    /**
     * ConsumerGroupOffsetInfo를 받아서 일괄 처리
     */
    fun requestToSeek(offsetSnapshot: ConsumerGroupOffsetSnapshot) {
        logger.info { "[ConsumerManager] Start to set offset. " +
                "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}], " +
                "partition count=[${offsetSnapshot.partitions.count()}]" }

        if (lock.tryLock()) {
            try {
                // offset seek 대상인 topic의 컨슈머를 찾음
                val targets = consumerCallbacks.values.filter { it.topic == offsetSnapshot.topic }
                    .associateBy { it.uniqueKey }

                if (targets.isEmpty()) {
                    logger.info { "[ConsumerManager] This listener does not have any consumer callback." }
                    return
                }

                offsetSnapshot.partitions.forEach { partitionSnapshot ->
                    val key = ConsumerCallback.getUniqueKey(
                        groupId = offsetSnapshot.groupId,
                        topic = offsetSnapshot.topic,
                        partition = partitionSnapshot.partition,
                    )

                    if (targets.containsKey(key)) {
                        val consumerCallback = targets[key]!!
                        consumerCallback.setSeek(partitionSnapshot.currentOffset)

                        logger.info { "[ConsumerManager] Offset has been set. " +
                                "groupId=[${consumerCallback.groupId}], topic=[${consumerCallback.topic}], " +
                                "partition=[${consumerCallback.partition}], offset=[${partitionSnapshot.currentOffset}]" }
                    }
                }
            } catch (e: Exception) {
                logger.error(e) { "[ConsumerManager] Offset seek error: ${e.message}" }
            } finally {
                lock.unlock()
                logger.info { "[ConsumerManager] Finished to set offset. " +
                        "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}]" }
            }
        } else {
            logger.info { "[ConsumerManager] Skipped to set offset because of lock. " +
                    "groupId=[${offsetSnapshot.groupId}], topic=[${offsetSnapshot.topic}]" }
        }
    }

    fun getConsumerCallback(
        groupId: String,
        topic: String,
        partition: Int,
    ): ConsumerCallback {
        val key = ConsumerCallback.getUniqueKey(groupId, topic, partition)
        return consumerCallbacks[key] ?: throw NoSuchElementException("No consumer callback found for key: $key")
    }

    fun getAllConsumerCallbacks(): List<ConsumerCallback> = consumerCallbacks.values.toList()

    fun register(
        groupId: String,
        topic: String,
        partition: Int,
        callback: ConsumerSeekAware.ConsumerSeekCallback,
    ) {
        val consumerCallback = ConsumerCallback(groupId, topic, partition, callback)

        if (consumerCallbacks.contains(consumerCallback.uniqueKey)) {
            logger.warn { "[ConsumerManager] Consumer is already registered with ConsumerManager. " +
                    "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
        } else {
            consumerCallbacks[consumerCallback.uniqueKey] = consumerCallback
            logger.info { "[ConsumerManager] Consumer registered with ConsumerManager. " +
                    "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
        }
    }

    fun revoke(
        groupId: String,
        topic: String,
        partition: Int,
    ) {
        val key = ConsumerCallback.getUniqueKey(groupId, topic, partition)
        consumerCallbacks.remove(key)

        logger.info { "[ConsumerManager] Consumer revoked from ConsumerManager. " +
                "groupId=[$groupId], topic=[$topic], partition=[$partition]" }
    }
}

package com.cowave.search.inbound_adapter.handler.config

import com.cowave.search.application.index.service.LegacySyncApplicationService
import com.cowave.search.inbound_adapter.handler.ConsumerCallbackManager
import com.cowave.search.inbound_adapter.handler.listener.ProductLegacySyncListener
import org.apache.avro.specific.SpecificRecord
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer

@Configuration
@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true")
class LegacySyncKafkaConfig(
    private val legacySyncConsumerProperties: LegacySyncConsumerProperties,
    private val legacySyncApplicationService: LegacySyncApplicationService,
    private val consumerCallbackManager: ConsumerCallbackManager,
) {
    @Bean
    fun productLegacySyncKafkaListenerContainer(): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val listener =
            ProductLegacySyncListener(
                legacySyncApplicationService = legacySyncApplicationService,
                groupId = legacySyncConsumerProperties.productCdc.groupId,
                consumerCallbackManager = consumerCallbackManager,
            )
        return DynamicIndexContainerFactory.createCdcContainer(
            dynamicIndexConsumer = legacySyncConsumerProperties.productCdc,
            listener = listener,
        )
    }
}

package com.cowave.search.inbound_adapter.handler.listener

import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.CatalogCdcEnvelope
import com.cowave.search.application.index.service.CatalogIndexApplicationService
import com.cowave.search.inbound_adapter.handler.ConsumerCallbackManager
import com.cowave.search.inbound_adapter.handler.mapper.toChangedCatalogData
import com.cowave.shared.utils.logger
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.Consumer
import org.apache.kafka.clients.consumer.ConsumerRecord
import org.springframework.kafka.listener.BatchAcknowledgingConsumerAwareMessageListener
import org.springframework.kafka.support.Acknowledgment

class CatalogDynamicIndexListener(
    private val catalogIndexApplicationService: CatalogIndexApplicationService,
    groupId: String,
    consumerCallbackManager: ConsumerCallbackManager,
) : FlinkCdcBatchListener(groupId, consumerCallbackManager),
    BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord> {
    private val logger by logger()

    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        runCatching {
            val changedDocuments =
                data
                    .filter { record ->
                        val envelope = record.value() as CatalogCdcEnvelope
                        val catalog = envelope.after ?: envelope.before
                        catalog != null && catalog.categoryId > 0
                    }.map { it.toChangedCatalogData() }

            val result = catalogIndexApplicationService.indexCatalogs(changedDocuments)

            logger.info { "Result of indexing: total=${result.totalCount}, success=${result.successCount}, failed=${result.failedCount}" }
        }.onSuccess {
            acknowledgment?.acknowledge()
            rewindIfNeeded()
        }.onFailure { ex ->
            logger.error(ex) { "Failed to index catalogs" }
        }.getOrThrow()
    }
}

